function simplify(text){
    text = String(text)

    text = text.replaceAll('&quot;'  ,"\"")
    text = text.replaceAll('&#096;'  ,"\'")
    text = text.replaceAll('&amp;'   ,"&")
    text = text.replaceAll('&equals;',`=`)
    text = text.replaceAll('&lt;'    ,`<`)
    text = text.replaceAll('&gt;'    ,`>`)

    return text;
}

